  "cookieCenter.contact.privacy": "privacidad@realaicoach.app",
  "cookieCenter.contact.support": "Espacio de Help & Support",
  "cookieCenter.contact.title": "Preguntas sobre cookies, consentimiento o estado del navegador",
  "cookieCenter.fact.consent.body": "El estado del navegador relacionado con el consentimiento nos ayuda a respetar elecciones de confianza previas.",
  "cookieCenter.fact.consent.title": "Registros de consentimiento",
  "cookieCenter.fact.control.body": "Las configuraciones del navegador y los flujos de privacidad te dan control significativo sobre el comportamiento de las cookies.",
  "cookieCenter.fact.control.title": "Control del usuario",
  "cookieCenter.fact.essential.body": "Se requiere algo de almacenamiento del navegador para el inicio de sesión, continuidad de sesión y seguridad de la cuenta.",
